package com.northstarbank.console.web;import com.northstarbank.console.security.EntitlementsAuthenticationProvider;import com.northstarbank.console.service.PasswordResetService;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.constraints.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.web.context.HttpSessionSecurityContextRepository;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;
@Controller public class LoginController{private final PasswordResetService resets;private final EntitlementsAuthenticationProvider identities;public LoginController(PasswordResetService r,EntitlementsAuthenticationProvider p){resets=r;identities=p;}@GetMapping("/login")String login(){return"login";}@GetMapping("/password-reset")String reset(){return"password-reset";}@PostMapping("/password-reset")String request(@RequestParam @Email String email){
  return resets.request(email)?"redirect:/login?resetRequested":"redirect:/login?unknownAccount";}
 @GetMapping("/password-reset/{token}")String resetToken(@PathVariable String token,Model m){m.addAttribute("token",token);m.addAttribute("valid",resets.valid(token));return"password-reset";}@PostMapping("/password-reset/{token}")String complete(@PathVariable String token,@RequestParam @Size(min=12,max=80)String password,HttpServletRequest request){String address=resets.complete(token,password);var context=SecurityContextHolder.createEmptyContext();context.setAuthentication(identities.authenticate(new UsernamePasswordAuthenticationToken(address,password)));SecurityContextHolder.setContext(context);
  request.getSession(true).setAttribute(HttpSessionSecurityContextRepository.SPRING_SECURITY_CONTEXT_KEY,context);return"redirect:/dashboard";}}
